-- Upgrade 2: a booking held for a short time, then let go.
-- In your own script these changes go inside CREATE TABLE.  Here, ALTER
-- TABLE makes them to the Appointment table that is already there.
ALTER TABLE Appointment ALTER COLUMN Status VARCHAR(12) NOT NULL;
ALTER TABLE Appointment ADD ExpiresOn DATETIME NULL;
ALTER TABLE Appointment DROP CONSTRAINT CK_Appointment_Status;
ALTER TABLE Appointment ADD CONSTRAINT CK_Appointment_Status
    CHECK (Status IN ('Provisional', 'Booked', 'Done', 'Cancelled'));
GO

CREATE OR ALTER PROCEDURE usp_Appointment_ExpireProvisional
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    -- A held booking whose time is up is cancelled.  The row stays as
    -- history, and the slot is free for someone else.
    UPDATE Appointment
    SET Status = 'Cancelled'
    WHERE Status = 'Provisional' AND ExpiresOn < GETDATE();
END
GO
